var LVL_NAME = { 1:'База', 2:'Средний', 3:'Сложный' };
var AVAILABLE_THEMES = Object.keys(THEME_NAMES).map(Number).filter(function(t){
  return Object.keys(TICKET_QUIZ).some(function(n){ return TICKET_THEME[n] === t; });
});
var QState = { theme:(AVAILABLE_THEMES[0] || 1), ticket:null, qs:[], idx:0, score:0, answered:false, sel:[] };

/* В 1-м семестре экран квиза открывается через showScreen: showTopic там
   ведёт в список билетов и про экран «quiz» не знает. */
function dqShowQuizScreen(){
  if (typeof showScreen === 'function') showScreen('quiz');
  else if (typeof showTopic === 'function') showTopic('quiz');
}

function dqLockSvg(){
  return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="5" y="11" width="14" height="10" rx="2"/><path d="M8 11V7a4 4 0 0 1 8 0v4"/></svg>';
}
function dqThemeShort(t){ return (THEME_NAMES[t]||('Тема '+t)).split('·')[0].trim(); }

function openQuizMenu(){
  dqShowQuizScreen();
  // если текущая тема под замком или пуста — берём первую доступную
  if (DEMO_LOCKED_THEMES.indexOf(QState.theme) >= 0) {
    var first = AVAILABLE_THEMES.filter(function(t){ return DEMO_LOCKED_THEMES.indexOf(t) < 0; })[0];
    QState.theme = (first != null) ? first : 1;
  }
  if (AVAILABLE_THEMES.indexOf(QState.theme) < 0 && AVAILABLE_THEMES.length) QState.theme = AVAILABLE_THEMES[0];
  var c = document.getElementById('quizContainer');

  var tabs = '';
  AVAILABLE_THEMES.forEach(function(t){
    var locked = DEMO_LOCKED_THEMES.indexOf(t) >= 0;
    tabs += '<button class="dq-tab' + (t===QState.theme ? ' active' : '') + (locked ? ' locked' : '') + '" '
          + 'onclick="' + (locked ? '' : 'dqSelectTheme(' + t + ')') + '">'
          + (locked ? '<span class="dq-lock">' + dqLockSvg() + '</span>' : '')
          + dqThemeShort(t) + '</button>';
  });

  var tickets = Object.keys(TICKET_QUIZ).map(Number)
    .filter(function(n){ return TICKET_THEME[n] === QState.theme; })
    .sort(function(a,b){ return a-b; });

  var grid = '';
  tickets.forEach(function(n){
    grid += '<button class="quiz-mode-card" onclick="dqStartTicket(' + n + ')">'
          + '<div class="dq-ticket-num">Билет ' + n + '</div>'
          + '<div class="qm-title" style="font-size:1.05rem;">' + (TITLES[n] || ('Билет ' + n)) + '</div>'
          + '</button>';
  });

  var locknote = '';
  if (DEMO_LOCKED_THEMES.length > 0) {
    locknote = '<div class="dq-locknote">Это демо. Открыта только <b>' + dqThemeShort(QState.theme)
             + '</b>. Остальные темы — в полной версии.</div>';
  }

  c.innerHTML =
      '<div class="quiz-header"><div class="quiz-header-top"><div>'
    + '<div class="topic-eyebrow">Подготовка по билетам</div>'
    + '<div class="quiz-title">Квизы</div></div>'
    + '<button class="quiz-back" onclick="showTopic(\'start\')">← На главную</button>'
    + '</div></div>'
    + '<p style="color:var(--ink-soft);font-size:0.95rem;margin-bottom:0.2rem;">Выбери тему и билет.</p>'
    + '<div class="dq-tabs">' + tabs + '</div>'
    + '<div style="color:var(--ink-mute);font-size:0.8rem;margin:0.1rem 0 0.2rem;">' + (THEME_NAMES[QState.theme] || '') + '</div>'
    + '<div class="quiz-mode-grid">' + grid + '</div>'
    + '<div style="color:var(--ink-mute);font-size:0.8rem;margin-top:0.9rem;">Готово билетов: '
    + Object.keys(TICKET_QUIZ).length + ' из ' + DQ_TOTAL + '. Остальные появятся по мере готовности.</div>'
    + locknote;

  if (window.MathJax && window.MathJax.typesetPromise) setTimeout(function(){ window.MathJax.typesetPromise([c]).catch(function(){}); }, 30);
  window.scrollTo({top:0, behavior:'smooth'});
}

function dqSelectTheme(t){
  if (DEMO_LOCKED_THEMES.indexOf(t) >= 0) return;
  QState.theme = t;
  openQuizMenu();
}

function dqShuffleQ(q){
  var idx = q.opts.map(function(o,i){
    return { o:o, c: Array.isArray(q.correct) ? (q.correct.indexOf(i) >= 0) : (i === q.correct) };
  });
  for (var i = idx.length - 1; i > 0; i--) {
    var j = Math.floor(Math.random() * (i + 1));
    var tmp = idx[i]; idx[i] = idx[j]; idx[j] = tmp;
  }
  var opts = idx.map(function(x){ return x.o; });
  var correct;
  if (Array.isArray(q.correct)) {
    correct = [];
    idx.forEach(function(x,i){ if (x.c) correct.push(i); });
  } else {
    correct = idx.findIndex(function(x){ return x.c; });
  }
  return { type:q.type, level:q.level, q:q.q, opts:opts, correct:correct, exp:q.exp };
}

function dqStartTicket(n){
  if (DEMO_LOCKED_THEMES.indexOf(TICKET_THEME[n]) >= 0) return;
  if (!TICKET_QUIZ[n]) return;
  QState.basics = false;
  QState.ticket = n;
  dqShowQuizScreen();
  QState.qs = TICKET_QUIZ[n].map(dqShuffleQ);
  QState.idx = 0; QState.score = 0; QState.answered = false; QState.sel = [];
  dqRenderQ();
}

function dqRenderQ(){
  var c = document.getElementById('quizContainer');
  var total = QState.qs.length, cur = QState.idx;
  if (cur >= total) { dqResult(); return; }
  var q = QState.qs[cur];
  var progress = Math.round((cur / total) * 100);
  var letters = ['А','Б','В','Г','Д','Е'];
  var isMulti = (q.type === 'multi');
  QState.sel = [];

  var opts = '';
  q.opts.forEach(function(opt,i){
    opts += '<button class="quiz-option" onclick="dqPick(' + i + ')" data-idx="' + i + '">'
          + '<span class="opt-letter">' + letters[i] + '</span><span class="opt-text">' + opt + '</span></button>';
  });

  var checkBtn = '<button class="quiz-btn quiz-btn-ghost" id="dqCheckBtn" onclick="dqCheck()" disabled>Проверить</button>';

  c.innerHTML =
      '<div class="quiz-header"><div class="quiz-header-top"><div>'
    + '<div class="topic-eyebrow">' + (QState.basics ? 'Термины прошлого семестра' : ('Билет ' + QState.ticket + ' · ' + dqThemeShort(QState.theme))) + '</div>'
    + '<div class="quiz-title">Вопрос ' + (cur+1) + ' / ' + total + '</div></div>'
    + '<button class="quiz-back" onclick="if(confirm(\'Прервать квиз?\')) ' + (QState.basics ? 'showTopic(\'basics\')' : 'openQuizMenu()') + '">✕ Выйти</button>'
    + '</div>'
    + '<div class="quiz-progress"><span>' + (cur+1) + ' / ' + total + '</span>'
    + '<div class="quiz-progress-bar"><div class="quiz-progress-fill" style="width:' + progress + '%"></div></div>'
    + '<span>' + QState.score + ' ✓</span></div></div>'
    + '<div class="quiz-question-card">'
    + '<div class="quiz-q-num">Вопрос ' + (cur+1) + '<span class="dq-lvl dq-lvl-' + q.level + '">' + (LVL_NAME[q.level]||'') + '</span></div>'
    + (isMulti ? '<div class="dq-hint">Можно выбрать несколько вариантов</div>' : '')
    + '<div class="quiz-q-text">' + q.q + '</div>'
    + '<div class="quiz-options" id="quizOptions">' + opts + '</div>'
    + '<div class="quiz-explanation" id="quizExplanation"></div>'
    + '<div class="quiz-controls">' + checkBtn
    + '<button class="quiz-btn quiz-btn-primary" id="quizNextBtn" onclick="dqNext()" disabled>' + ((cur+1===total) ? 'Завершить' : 'Дальше →') + '</button>'
    + '</div></div>';

  QState.answered = false;
  if (window.MathJax && window.MathJax.typesetPromise) setTimeout(function(){ window.MathJax.typesetPromise([c]).catch(function(){}); }, 30);
  window.scrollTo({top:0, behavior:'instant'});
}

function dqPick(i){
  if (QState.answered) return;
  var q = QState.qs[QState.idx];
  var isMulti = (q.type === 'multi');
  if (isMulti){
    var p = QState.sel.indexOf(i);
    if (p >= 0) QState.sel.splice(p,1); else QState.sel.push(i);
  } else {
    QState.sel = [i];
  }
  var btns = document.querySelectorAll('#quizOptions .quiz-option');
  btns.forEach(function(b,bi){ b.classList.toggle('selected', QState.sel.indexOf(bi) >= 0); });
  var cb = document.getElementById('dqCheckBtn');
  if (cb) cb.disabled = (QState.sel.length === 0);
}

function dqCheck(){
  if (QState.answered) return;
  if (QState.sel.length === 0) return;
  QState.answered = true;
  var cb = document.getElementById('dqCheckBtn'); if (cb) cb.disabled = true;
  dqReveal(QState.qs[QState.idx], QState.sel.slice());
}

function dqReveal(q, chosen){
  var correctSet = Array.isArray(q.correct) ? q.correct : [q.correct];
  var btns = document.querySelectorAll('#quizOptions .quiz-option');
  btns.forEach(function(b,i){
    b.disabled = true; b.classList.remove('selected');
    var isC = correctSet.indexOf(i) >= 0;
    var isS = chosen.indexOf(i) >= 0;
    if (isC && isS) b.classList.add('correct');
    else if (!isC && isS) b.classList.add('wrong');
    else if (isC && !isS) b.classList.add('correct');
  });
  var ok = (chosen.length === correctSet.length) && chosen.every(function(i){ return correctSet.indexOf(i) >= 0; });
  if (ok) QState.score++;
  var e = q.exp || {};
  var html = '<div class="exp-verdict ' + (ok ? 'ok' : 'no') + '"><span class="ic">' + (ok ? '✓' : '✕') + '</span>' + (ok ? 'Верно' : 'Неточно') + '</div>';
  if (typeof e === 'string') {
    html += '<div class="exp-section detail"><div class="sec-body">' + e + '</div></div>';
  } else {
    if (e.tldr)    html += '<div class="exp-tldr"><span class="bulb">💡</span><span class="t"><span class="lbl">В двух словах. </span>' + e.tldr + '</span></div>';
    if (e.detail)  html += '<div class="exp-section detail"><div class="sec-lbl">Разбор</div><div class="sec-body">' + e.detail + '</div></div>';
    if (e.variants)html += '<div class="exp-section variants"><div class="sec-lbl">Почему не остальные</div><div class="sec-body">' + e.variants + '</div></div>';
  }
  var ex = document.getElementById('quizExplanation');
  ex.innerHTML = html;
  ex.classList.add('show');
  var nb = document.getElementById('quizNextBtn'); if (nb) nb.disabled = false;
  if (window.MathJax && window.MathJax.typesetPromise) setTimeout(function(){ window.MathJax.typesetPromise([ex]).catch(function(){}); }, 30);
}

function dqNext(){ QState.idx++; dqRenderQ(); window.scrollTo({top:0, behavior:'instant'}); }

function dqResult(){
  var c = document.getElementById('quizContainer');
  var total = QState.qs.length, pct = Math.round((QState.score / total) * 100);
  var msg;
  if (pct === 100) msg = QState.basics ? 'Идеально! Термины освоены.' : 'Идеально! Билет освоен.';
  else if (pct >= 85) msg = 'Отличный результат.';
  else if (pct >= 70) msg = 'Хорошо, но есть над чем поработать.';
  else if (pct >= 50) msg = QState.basics ? 'Половина есть. Стоит повторить термины.' : 'Половина есть. Стоит повторить теорию билета.';
  else msg = 'Нужно повторить материал и пройти снова.';
  var againBtn = QState.basics
    ? '<button class="quiz-btn quiz-btn-primary" onclick="startBasicsQuiz()">Пройти снова</button>'
      + '<button class="quiz-btn quiz-btn-ghost" onclick="showTopic(\'basics\')">К терминам</button>'
    : '<button class="quiz-btn quiz-btn-primary" onclick="dqStartTicket(' + QState.ticket + ')">Пройти снова</button>'
      + '<button class="quiz-btn quiz-btn-ghost" onclick="openQuizMenu()">Другой билет</button>';
  c.innerHTML =
      '<div class="quiz-header"><div class="quiz-header-top"><div>'
    + '<div class="topic-eyebrow">' + (QState.basics ? 'Термины · итог' : ('Билет ' + QState.ticket + ' · итог')) + '</div>'
    + '<div class="quiz-title">Результат</div></div></div></div>'
    + '<div class="quiz-result"><div class="quiz-result-score">' + QState.score + ' / ' + total + '</div>'
    + '<div class="quiz-result-label">' + pct + '% правильных</div>'
    + '<div class="quiz-result-message">' + msg + '</div>'
    + '<div class="quiz-result-actions">'
    + againBtn
    + '<button class="quiz-btn quiz-btn-ghost" onclick="showTopic(\'start\')">На главную</button>'
    + '</div></div>';
  window.scrollTo({top:0, behavior:'smooth'});
}

function startBasicsQuiz(){
  dqShowQuizScreen();
  QState.basics = true;
  QState.ticket = null;
  QState.qs = BASICS_QUIZ.map(dqShuffleQ);
  QState.idx = 0; QState.score = 0; QState.answered = false; QState.sel = [];
  dqRenderQ();
}

